get_customer_portal.code:
const response = await client.customerPortal.getCustomerPortal();
const settings = response.map.customer_portal;
console.log(settings.portal.enabled, settings.registration.enabled);
console.log(settings.login.password_recovery, settings.login.registration_link);

patch_customer_portal.code:
const response = await client.customerPortal.patchCustomerPortal({
    customer_portal: {
        login: {registration_link: false},
        sso: {azure_ad: {data_mapping: {city: 'city'}}},
    },
});
const settings = response.map.customer_portal;
console.log(settings.login.registration_link);
console.log(settings.sso.azure_ad.data_mapping.city);

get_customer_portal_section.code:
const response = await client.customerPortal.getCustomerPortalSection('login');
const login = response.map.login;
console.log(login.enabled, login.password_recovery, login.registration_link);
